    pairs = {')': '(', ']': '[', '}': '{'}
    st: list[str] = []
    for ch in s:
        if ch in pairs.values():
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return False
    return not st

