    intervals.sort(key=lambda x: x[0])
    out: list[list[int]] = []
    for cur in intervals:
        if not out or out[-1][1] < cur[0]:
            out.append(cur[:])
        else:
            out[-1][1] = max(out[-1][1], cur[1])
    return out

