public class Solution {
    static boolean dfs(char[][] board, String word, int i, int r, int c, boolean[][] used) {
        if (i == word.length()) return true;
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return false;
        if (used[r][c] || board[r][c] != word.charAt(i)) return false;

        used[r][c] = true;
        boolean ok = dfs(board, word, i + 1, r + 1, c, used)
                || dfs(board, word, i + 1, r - 1, c, used)
                || dfs(board, word, i + 1, r, c + 1, used)
                || dfs(board, word, i + 1, r, c - 1, used);
        used[r][c] = false;
        return ok;
    }

    static boolean exist(char[][] board, String word) {
        boolean[][] used = new boolean[board.length][board[0].length];
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (dfs(board, word, 0, r, c, used)) return true;
            }
        }
        return false;
    }
}

