def exist(board: list[list[str]], word: str) -> bool:
    rows, cols = len(board), len(board[0])
    used: set[tuple[int, int]] = set()

    def dfs(i: int, r: int, c: int) -> bool:
        if i == len(word):
            return True
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return False
        if (r, c) in used or board[r][c] != word[i]:
            return False

        used.add((r, c))
        ok = (
            dfs(i + 1, r + 1, c)
            or dfs(i + 1, r - 1, c)
            or dfs(i + 1, r, c + 1)
            or dfs(i + 1, r, c - 1)
        )
        used.remove((r, c))
        return ok

    for r in range(rows):
        for c in range(cols):
            if dfs(0, r, c):
                return True
    return False

