        for (int[] pair : bucket) {
            if (pair[0] == key) { pair[1] = value; return; }
        }
        bucket.add(new int[]{key, value});
    }

    Integer get(int key) {
        for (int[] pair : buckets.get(idx(key))) {
            if (pair[0] == key) return pair[1];
        }
        return null;
    }
